"""Independent direct simulation of the case/event lifecycle for cross-checking."""
import heapq

MAX = (1 << 63) - 1


def simulate(cases, events, timeout_ms):
    """cases: [{'name','frames','expect'}]; frames are dicts with compiled values.
    events: [{'at','kind',...}] with compiled 'fields'/'data'.
    Returns per-case dicts with state/at/frames/request_frames/payload_bytes/
    sent-event-list/received-event-list/response_frames/body-parts."""
    streams = [4 * i for i in range(len(cases))]
    state = [None] * len(cases)          # terminal state
    at = [None] * len(cases)
    index = [0] * len(cases)             # next frame index
    send_ended = [False] * len(cases)
    exhausted = [False] * len(cases)
    response_ended = [False] * len(cases)
    waiting = [False] * len(cases)
    closed = [False] * len(cases)
    sent_log = [[] for _ in cases]       # (time, kind, data, end)
    recv_log = [[] for _ in cases]
    body_parts = [[] for _ in cases)

    heap = []
    seq = [0]

    def push(time, kind, order, action):
        seq[0] += 1
        heapq.heappush(heap, (time, kind, order, seq[0], action))

    for i in range(len(cases)):
        push(0, -1, i, ('start', i))
    for j, ev in enumerate(events):
        push(ev['at'], 0, j, ('event', j))

    def emit(i, now, item):
        kind = item['Type']
        if kind == 'headers':
            sent_log[i].append((now, 'H', item['data_to_transfered'], item['End_Stream']))
            if item['End_Stream']:
                send_ended[i] = True
        elif kind == 'data':
            sent_log[i].append((now, 'D', item['data_to_transfered'], item['End_Stream']))
            if item['End_Stream']:
                send_ended[i] = True
        else:
            sent_log[i].append((now, 'G', item['data_to_transfered'], False))

    def run_frames(i, now):
        """Run frames until a sleep or terminal; returns nothing."""
        while index[i] < len(cases[i]['frames']):
            item = cases[i]['frames'][index[i]]
            if item['Type'] == 'sleep':
                index[i] += 1
                push(now + item['Time_to_Stop'], 1, i, ('resume', i))
                return
            if send_ended[i]:
                state[i] = 'send_error'
                at[i] = now
                return
            index[i] += 1
            emit(i, now, item)
        exhausted[i] = True
        if response_ended[i]:
            state[i] = 'ok'
            at[i] = now
        else:
            waiting[i] = True
            push(now + timeout_ms, 2, i, ('timeout', i))

    while heap:
        now, _, _, _, action = heapq.heappop(heap)
        tag = action[0]
        if tag == 'start':
            i = action[1]
            run_frames(i, now)
        elif tag == 'resume':
            i = action[1]
            if state[i] is not None:
                continue
            run_frames(i, now)
        elif tag == 'timeout':
            i = action[1]
            if state[i] is None and waiting[i]:
                state[i] = 'timeout'
                at[i] = now
        else:
            j = action[1]
            ev = events[j]
            if ev['kind'] == 'close':
                if closed[0] if False else any(closed):
                    continue
                closed[0] if False else None
                # first close only
                if not _closed_flag[0]:
                    _closed_flag[0] = True
                    for i in range(len(cases)):
                        if state[i] is None:
                            state[i] = 'closed'
                            at[i] = now
            else:
                stream = ev['stream']
                if stream not in streams:
                    continue
                i = streams.index(stream)
                if state[i] is not None or response_ended[i]:
                    continue
                if ev['kind'] == 'headers':
                    recv_log[i].append((now, 'h', ev['fields'], ev['end']))
                else:
                    recv_log[i].append((now, 'd', ev['data'], ev['end']))
                    body_parts[i].append(ev['data'])
                if ev['end']:
                    response_ended[i] = True
                    if waiting[i] and state[i] is None:
                        state[i] = 'ok'
                        at[i] = now
    out = []
    for i, case in enumerate(cases):
        frames = sum(1 for entry in sent_log[i])
        request_frames = sum(1 for entry in sent_log[i] if entry[1] in ('H', 'D'))
        payload = 0
        for _, kind, data, _ in sent_log[i]:
            if kind == 'H':
                payload += sum(len(n) + len(v) for n, v in data)
            else:
                payload += len(data)
        out.append({'name': case['name'], 'stream': streams[i],
                    'state': state[i], 'at': at[i], 'frames': frames,
                    'request_frames': request_frames, 'payload_bytes': payload,
                    'sent': sent_log[i], 'received': recv_log[i],
                    'response_frames': len(recv_log[i]), 'body': body_parts[i]})
    return out


